//   - Auto SEL mode exit (registerSelectionModeToggle / selection_mode_norm)
//   - Selset deactivation (drainSelsets_ on actReq == -1)
// Frank 2026-05-21.
std::atomic<bool> g_pendingFollowSelectedAfterRebuild{false};
// Main-thread drain flags. Lambdas registered as builtins can fire
// from the libusb input thread; ProjExtState + track-API calls must
// run on the main thread. Drained in onTimer before
// rebuildVisibleTrackList so the rebuilt list reflects the new state.
//   activate: 1..8 = recall slot, -1 = clear
//   save:     1..8 = snapshot current REAPER selection into slot
std::atomic<int>  g_selsetActivateRequest{0};
std::atomic<int>  g_selsetSaveRequest{0};

// CS-Switch requests — the switch builtins fire from the UF8/UC1 input thread
// (onUf8Input → bindings::dispatch), but TrackFX_AddByName auto-floats the new
// plug-in's config window and creating that NSWindow off the main thread aborts
// (see feedback-reaper-api-input-thread). So the builtins only POST here; the
// main-thread onTimer drain runs the actual swap. Frank 2026-06-20.
//   switch req: 0..7 = favourite slot to switch to, -1 = none
//   cycle  req: accumulated signed detents (0 = none)
std::atomic<int>  g_csSwitchReq{-1};
std::atomic<int>  g_csCopyReq{-1};
std::atomic<int>  g_csCycleReq{0};
// Bus-Compressor favourites — exact analog of the CS request atomics.
std::atomic<int>  g_bcSwitchReq{-1};
std::atomic<int>  g_bcCopyReq{-1};
std::atomic<int>  g_bcCycleReq{0};
// FX move-in-chain req: accumulated signed detents (0 = none). Posted by the
// REAPER-action route (hookCommand2); the surface builtins call the worker
// directly. Drained on the main thread (TrackFX_CopyToTrack).
std::atomic<int>  g_fxMoveReq{0};
// Dynamic soft-key bank press, posted from the input thread (onUf8Input) and
// drained on the main thread (REAPER send/FX/track API is main-thread-only).
// Encoding: 0 = none; else (1<<24) | (kind<<16) | (slot<<8) | gesture, where
// gesture 0=plain push, 1=+Shift, 2=+Cmd, 3=+Ctrl, 4=long-press.
std::atomic<uint32_t> g_dynBankReq{0};
// Page-delta for a bankable dynamic bank (FX / Sends), posted from the input
// thread (UF8 encoder / Bank buttons) and drained on the main thread.
std::atomic<int> g_dynBankPageReq{0};
// After an explicit FX-bank Focus/Solo, suppress chaseLastTouchedFx until this
// timestamp so REAPER's stale last-touched FX (e.g. a just-bypassed BC) can't
// yank focus + the GUI back off the FX the user just picked. ms (nowMs_).
std::atomic<int64_t> g_dynFxFocusLockUntilMs{0};
static void applyDynBankReq_(uint32_t enc);          // main-thread executor
static int  engagedBankableKind_();                  // any thread
static void pageDynBank_(int kind, int delta);       // main thread
static void tickDynBankPaging_();                    // main thread (onTimer)
static bool syncInstanceFromFxIdx_(MediaTrack* tr, int fxIdx,
                                   bool setFocusedDomain, bool setBcAnchor);
int  stripInstanceActiveFx_(MediaTrack* tr);         // focused FX index
void landFxCursor_(MediaTrack* tr, const std::vector<int>& ring, int k);
void triggerPluginModeFollowSync_();                 // re-point plugin-mode GUI
static void pinFxGuiIfEnabled_(MediaTrack* tr, int fxIdx);
static void applyCsSwitch_(int slot, bool ownSettings = false);  // CS-Switch block
static void applyCsCopy_(int slot);     // copy-below-and-bypass variant
static void applyCsCycle_(int step, bool ownSettings = false);
static void applyBcSwitch_(int slot, bool ownSettings = false);  // BC analogs
static void applyBcCopy_(int slot);
static void applyBcCycle_(int step, bool ownSettings = false);
static void applyFxMoveSlotAware_(int step, bool carousel);

// True when REAPER is currently honouring TCP track pins. The two TCP-pin
// view actions are NON-destructive — they don't clear B_TCPPIN — so to
// mirror what REAPER actually shows we must read their toggle state:
//   43573 = Track: Override/unpin all pinned tracks in TCP
//   43575 = Track: Show/hide all pinned tracks in TCP
// Either active → pins not honoured → our TCP-pin sticky stands down (the
// B_TCPPIN tracks bank like normal tracks). IDs from Frank's Action List
// 2026-06-22. State -1 (unknown) defaults to "respected" so we never
// regress the baseline. NOTE: the toggle DIRECTION (does state==1 mean
// shown/hidden, overridden/not?) is HW-verify pending — flip a comparison
// if a capture shows it inverted. Focus-Set pins are NOT affected by these
// (own concept, own Recall toggle).
inline bool tcpPinsRespected_() {
    const int ov = GetToggleCommandState2(SectionFromUniqueID(0), 43573);
    const int hd = GetToggleCommandState2(SectionFromUniqueID(0), 43575);
    return ov != 1 && hd != 1;
}

// Is this track a member of the active Focus Set? The Focus Set (formerly
// "Temporary Selection Set") is now a PIN source, not a filter: members
// stick to the leftmost strips, nothing is hidden. Empty/inactive → false.
inline bool isFocusMember_(MediaTrack* tr) {
    if (!tr || !g_tempSelsetActive.load() || g_tempSelsetGuids.empty())
        return false;
    char guidBuf[64] = {0};
    GetSetMediaTrackInfo_String(tr, "GUID", guidBuf, false);
    return g_tempSelsetGuids.count(guidBuf) != 0;
}

void rebuildVisibleTrackList() {
    const bool folderMode = g_folderMode.load();
    const bool selOnly    = g_showOnlySelected.load();
    if (!g_spilledParents.empty()) {
        for (auto it = g_spilledParents.begin(); it != g_spilledParents.end();) {
            if (!ValidatePtr2(nullptr, *it, "MediaTrack*")) it = g_spilledParents.erase(it);
            else ++it;
        }
    }
    const int  n = CountTracks(nullptr);
    g_visibleTracks.clear();
    g_visibleTracks.reserve(static_cast<size_t>(n));
    for (int i = 0; i < n; ++i) {
        MediaTrack* tr = GetTrack(nullptr, i);
        if (!tr) continue;
        if (folderMode) {
            // Parents-only with strict ancestor-chain spill: a track
            // passes when it's at top level (depth==0) — covers folder-
            // start and non-folder root tracks alike — OR every ancestor
            // folder up the chain is in g_spilledParents. Walking the
            // chain (instead of just checking the direct parent) means
            // collapsing a Level-1 folder hides its Level-3 grandchildren
            // even if their Level-2 parent is still in the set; the
            // grandchildren reappear on re-spill of Level-1 without us
            // having to track snapshot state.
            const int depth = GetTrackDepth(tr);
            if (depth != 0) {
                if (g_spilledParents.empty()) continue;
                MediaTrack* anc = GetParentTrack(tr);
                bool chainOk = true;
                while (anc) {
                    if (!g_spilledParents.count(anc)) { chainOk = false; break; }
                    anc = GetParentTrack(anc);
                }
                if (!chainOk) continue;
            }
        }
        // Show-only-selected: live filter against current selection (not
        // a saved selection set). Each tick reflects the latest
        // I_SELECTED state so toggling track selection adds/removes
        // strips immediately.
        if (selOnly && !(GetMediaTrackInfo_Value(tr, "I_SELECTED") > 0.5))
            continue;
        // Active Selection-Set filter — independent of, and ANDed with,
        // the other gates above (Frank 2026-05-16). Empty set =
        // pass-through so an active-but-empty slot doesn't hide
        // everything. Snapshot slots populate the set once on activation;
        // Group slots refresh it each tick before rebuild fires (both
        // paths live in the onTimer drain).
        if (g_selsetActive.load() > 0 && !g_selsetActiveGuids.empty()) {
            char guidBuf[64] = {0};
            GetSetMediaTrackInfo_String(tr, "GUID", guidBuf, false);
            if (!g_selsetActiveGuids.count(guidBuf)) continue;
        }
        // Focus Set (formerly "Temporary Selection Set") is NO LONGER a
        // filter — it's a PIN source now. Members are NOT hidden here;
        // they get floated to the leftmost strips by the pin partition
        // below (isFocusMember_) and reserved by stripToVisibleSlot.
        // Filtering is exclusively the slot-Selset job above.
        // AUTO-mode filter: hide tracks in Trim/Read (0) or Read (1) so
        // the user only sees tracks armed for automation writing. Only
        // active while SelectionMode == Auto AND the Settings toggle is
        // on — otherwise tracks of any automation mode pass through.
        // Focus-Set members are EXEMPT — an explicit pin is a stronger
        // intent than the "hide unarmed" convenience filter, so a pinned
        // member stays visible even in Trim/Read. (Set the Focus-Set
        // Auto-Mode to Touch/Write if you want them auto-armed instead.)
        if (g_autoHideReadTrim.load()
            && g_selectionMode.load() == SelectionMode::Auto
            && !isFocusMember_(tr))
        {
            const int am = GetTrackAutomationMode(tr);
            if (am == 0 || am == 1) continue;
        }
        // Visibility-follow filter: the surface mirrors what's visible
        // in REAPER's selected view (TCP or MCP). IsTrackVisible folds
        // both the per-track B_SHOWIN* flag AND ancestor folder-collapse
        // state into one call, so children of a collapsed folder are
        // dropped in TCP-mode without us having to walk the hierarchy.
        // B_SHOWIN* alone misses the folder-collapse case. Frank 2026-05-22.
        const bool followMcp = (g_visibilityFollow.load() == 1);
        if (!IsTrackVisible(tr, followMcp)) continue;
        g_visibleTracks.push_back(tr);
    }

    // Pin head: float pinned tracks to the front so they occupy the
    // leftmost strips (stripToVisibleSlot reserves strips 0..P-1 for them).
    // ONE stable_partition over a combined predicate — relative order is
    // preserved (pinned tracks stay in REAPER track-number order) and a
    // track that is BOTH a Focus member and TCP-pinned counts once:
    //   - Focus-Set members — BOTH TCP and MCP modes (our own concept).
    //   - REAPER TCP pins (B_TCPPIN) — TCP mode only, and only while REAPER
    //     is actually honouring pins (tcpPinsRespected_; mirrors the
    //     Override/Show-Hide view toggles). MCP has no pin region.
    int pinnedCount = 0;
    if (!g_visibleTracks.empty()) {
        const bool tcpPins = (g_visibilityFollow.load() == 0)
                          && tcpPinsRespected_();
        auto firstNonPinned = std::stable_partition(
            g_visibleTracks.begin(), g_visibleTracks.end(),
            [tcpPins](MediaTrack* tr) {
                if (isFocusMember_(tr)) return true;
                return tcpPins
                    && GetMediaTrackInfo_Value(tr, "B_TCPPIN") > 0.5;
            });
        pinnedCount = static_cast<int>(firstNonPinned - g_visibleTracks.begin());
    }
    g_pinnedCount.store(pinnedCount);

    // Clamp bankOffset when a filter (selset / show-only-selected /
    // folder mode) shrinks the list past the current offset, so the
    // surface doesn't end up with every strip empty. Only fires when
    // ALL strips would be empty (curOff >= vc) — partial-fill banks
    // (e.g. vc=10 + off=8 showing 2 tracks on strips 0-1) are valid
    // user-intended positions and stay untouched. Frank 2026-05-16.
    const int vc     = static_cast<int>(g_visibleTracks.size());
    const int curOff = g_bankOffset.load();
    const int esc    = effectiveStripCount_();
    const int maxOff = (vc > esc) ? vc - esc : 0;
    if (curOff >= vc && curOff > maxOff) {
        g_bankOffset.store(maxOff);
        g_bankDirty.store(true);
    }
}

// ---- Selection-Set helpers ------------------------------------------------
// All called from the main thread (onTimer drain) — REAPER's ProjExtState +
// track-API calls aren't safe from the libusb input thread.

// REAPER track-group categories. Each has its own 32-bit (low) and
// 32-bit (high) bitmask. "ANY group flag" semantics OR across all of
// these (Frank 2026-05-16). Keep in sync with REAPER's documented
// param names for GetSetTrackGroupMembership / *High.
inline const char* const* selsetGroupCategories_(int* outCount) {
    static const char* kCats[] = {
        // Media / razor-edit grouping (Frank 2026-05-16). Most projects
        // assign tracks to a group via the TCP context menu's "Track
        // Grouping Parameters" → Media/Razor Edits checkbox, NOT via
        // the per-parameter Lead/Follow rows. Without these two
        // categories the live track count stays 0 even when REAPER
        // shows the tracks as group members.
        "MEDIA_EDIT_LEAD",  "MEDIA_EDIT_FOLLOW",
        "VOLUME_LEAD",      "VOLUME_FOLLOW",
        "VOLUME_VCA_LEAD",  "VOLUME_VCA_FOLLOW",
        "PAN_LEAD",         "PAN_FOLLOW",
        "WIDTH_LEAD",       "WIDTH_FOLLOW",
        "MUTE_LEAD",        "MUTE_FOLLOW",
        "SOLO_LEAD",        "SOLO_FOLLOW",
        "RECARM_LEAD",      "RECARM_FOLLOW",
        "POLARITY_LEAD",    "POLARITY_FOLLOW",
        "AUTOMODE_LEAD",    "AUTOMODE_FOLLOW",
    };
    *outCount = static_cast<int>(sizeof(kCats) / sizeof(kCats[0]));
    return kCats;
}

bool trackInGroup_(MediaTrack* tr, int groupIdx) {
    if (!tr || groupIdx < 1 || groupIdx > 64) return false;
    int count = 0;
    const char* const* cats = selsetGroupCategories_(&count);
    if (groupIdx <= 32) {
        const unsigned bit = 1u << (groupIdx - 1);
        for (int i = 0; i < count; ++i) {
            unsigned m = GetSetTrackGroupMembership(tr, cats[i], 0, 0);
            if (m & bit) return true;
        }
    } else {
        const unsigned bit = 1u << (groupIdx - 33);
        for (int i = 0; i < count; ++i) {
            unsigned m = GetSetTrackGroupMembershipHigh(tr, cats[i], 0, 0);
            if (m & bit) return true;
        }
    }
    return false;
}

std::string trackGuidStr_(MediaTrack* tr) {
    if (!tr) return std::string{};
    char buf[64] = {0};
    GetSetMediaTrackInfo_String(tr, "GUID", buf, false);
    return std::string(buf);
}

// Serialize a slot as TAB-separated fields. We initially used '\n' as
// the delimiter, but global slots ride ExtState (reaper-extstate.ini),
// which is line-oriented and silently truncates / corrupts multi-line
// values. Tab is safe in both ExtState (.ini) and ProjExtState
// (rpp-embedded). Field 0 = type ("group"|"snapshot"), field 1 = name,
// field 2..N = groupIdx (Group) or one GUID per field (Snapshot).
inline constexpr char kSelsetDelim = '\t';
std::string selsetSerialize_(const SelSet& s) {
    std::string out;
    out.reserve(64 + s.guids.size() * 40);
    out += (s.type == SelSetType::Group) ? "group" : "snapshot";
    out += kSelsetDelim;
    out += s.name;
    out += kSelsetDelim;
    if (s.type == SelSetType::Group) {
        char num[16];
        snprintf(num, sizeof(num), "%d", s.groupIdx);
        out += num;
    } else {
        for (size_t i = 0; i < s.guids.size(); ++i) {
            if (i > 0) out += kSelsetDelim;
            out += s.guids[i];
        }
    }
    return out;
}

void selsetDeserialize_(const char* raw, SelSet& out) {
    out = SelSet{};
    if (!raw || !*raw) return;
    std::string s(raw);
    // Back-compat: pre-2026-05-16 format used '\n' as delimiter. If we
    // see one, convert in-place so old ProjExtState payloads still load.
    for (auto& c : s) if (c == '\n') c = kSelsetDelim;
    auto popField = [&]() -> std::string {
        auto p = s.find(kSelsetDelim);
        std::string field = (p == std::string::npos) ? s : s.substr(0, p);
        s.erase(0, (p == std::string::npos) ? s.size() : p + 1);
        return field;
    };
    const std::string typeStr = popField();
    out.type = (typeStr == "group") ? SelSetType::Group : SelSetType::Snapshot;
    out.name = popField();
    if (out.type == SelSetType::Group) {
        const std::string n = popField();
        out.groupIdx = std::atoi(n.c_str());
        if (out.groupIdx < 1 || out.groupIdx > 64) out.groupIdx = 1;
    } else {
        while (!s.empty()) {
            std::string g = popField();
            if (!g.empty()) out.guids.push_back(std::move(g));
        }
    }
}

// Storage routing helpers. Flag key is ALWAYS in ExtState so we know
// which content key to read from on load. Content lives in either
// ExtState (global) or ProjExtState (per-project) based on the flag.
inline void selsetKeyFlag_(int slot, char* out, size_t n) {
    snprintf(out, n, "selset_%d_scope", slot);
}
inline void selsetKeyDataGlobal_(int slot, char* out, size_t n) {
    snprintf(out, n, "selset_%d_data", slot);
}
inline void selsetKeyDataProject_(int slot, char* out, size_t n) {
    snprintf(out, n, "selset_%d", slot);
}

void selsetWriteToProject_(int slot1to8) {
    if (slot1to8 < 1 || slot1to8 > 8) return;
    const SelSet& s = g_selsets[slot1to8 - 1];
    // Persist the scope flag (always in global ExtState, reliable).
    char flagKey[32];
    selsetKeyFlag_(slot1to8, flagKey, sizeof(flagKey));
    SetExtState("rea_sixty", flagKey, s.global ? "global" : "project", true);

    const bool isEmpty = s.name.empty() && s.guids.empty()
                      && s.type == SelSetType::Snapshot;
    const std::string serialized = isEmpty ? "" : selsetSerialize_(s);

    char globalKey[32];
    selsetKeyDataGlobal_ (slot1to8, globalKey, sizeof(globalKey));
    if (s.global) {
        // Global write — reliable via SetExtState.
        SetExtState("rea_sixty", globalKey, serialized.c_str(), true);
    } else {
        // Project-scoped data goes through the projectconfig hook below
        // (slotsSaveExt_). SetProjExtState was unreliable on Frank's
        // build — see setprojextstate-not-reliable.md. MarkProjectDirty
        // gets the user a Save prompt so the hook gets a chance to run.
        if (ReaProject* p = EnumProjects(-1, nullptr, 0)) MarkProjectDirty(p);
        // Clear any stale global mirror so a switch from global → project
        // doesn't leave two copies floating around.
        SetExtState("rea_sixty", globalKey, "", true);
    }
}

// projectconfig hooks for the 1..8 Selection Set slots — project-scoped
// data. Mirrors the temp-selset pattern (see g_tempSelsetProjConfig).
// Global-scoped slots stay on SetExtState (reliable) and are skipped
// by these callbacks. Each populated project-scoped slot writes one
// line: `SELSET_<N>_DATA "<serialized>"` where serialised is the same
// TAB-delimited format selsetSerialize_ produces.
void slotsSaveExt_(ProjectStateContext* ctx, bool /*isUndo*/,
                   struct project_config_extension_t* /*reg*/)
{
    for (int i = 1; i <= 8; ++i) {
        const SelSet& s = g_selsets[i - 1];
        if (s.global) continue;
        const bool isEmpty = s.name.empty() && s.guids.empty()
                          && s.type == SelSetType::Snapshot;
        if (isEmpty) continue;
        const std::string serialized = selsetSerialize_(s);
        ctx->AddLine("SELSET_%d_DATA \"%s\"", i, serialized.c_str());
    }
}

bool slotsProcessLine_(const char* line, ProjectStateContext* /*ctx*/,
                       bool /*isUndo*/,
                       struct project_config_extension_t* /*reg*/)
{
    if (!line || !*line) return false;
    const char* p = line;
    while (*p == ' ' || *p == '\t') ++p;
    if (std::strncmp(p, "SELSET_", 7) != 0) return false;
    p += 7;
    int slot = 0;
    while (*p >= '0' && *p <= '9') { slot = slot * 10 + (*p - '0'); ++p; }
    if (slot < 1 || slot > 8) return false;
    if (std::strncmp(p, "_DATA", 5) != 0) return false;
    p += 5;
    while (*p == ' ' || *p == '\t') ++p;
    if (*p == '"') ++p;
    std::string field;
    while (*p && *p != '"') field += *p++;
    selsetDeserialize_(field.c_str(), g_selsets[slot - 1]);
    g_selsets[slot - 1].global = false;
    return true;
}

void slotsBeginLoad_(bool /*isUndo*/,
                     struct project_config_extension_t* /*reg*/)
{
    // Reset only project-scoped slots — global slots are independent of
    // the project and stay loaded from SetExtState (refreshed by
    // loadSelsetsFromProject_'s flag-driven path).
    for (int i = 0; i < 8; ++i) {
        if (!g_selsets[i].global) g_selsets[i] = SelSet{};
    }
}

project_config_extension_t g_slotsProjConfig{
    slotsProcessLine_,
    slotsSaveExt_,
    slotsBeginLoad_,
    nullptr
};

// projectconfig hooks for Parameter-Group ON/OFF flags — per-project so a new
// empty project always loads with every group off (membership is already
// per-project via the tracks' P_EXT mask). Group NAMES stay global
// (parameter_groups.json). One line: `PG_ACTIVE <8 bits>` e.g. PG_ACTIVE 01010000.
void pgActiveSaveExt_(ProjectStateContext* ctx, bool /*isUndo*/,
                      struct project_config_extension_t* /*reg*/)
{
    const std::string bits = uf8::param_groups::activeFlagsBits();
    if (bits.find('1') != std::string::npos)
        ctx->AddLine("PG_ACTIVE %s", bits.c_str());
    // Per-group names — one `PG_NAME <slot> "<name>"` line per named group.
    for (int i = 0; i < uf8::param_groups::kSlotCount; ++i) {
        const std::string nm = uf8::param_groups::groupName(i);
        if (!nm.empty()) ctx->AddLine("PG_NAME %d \"%s\"", i, nm.c_str());
    }
}

bool pgActiveProcessLine_(const char* line, ProjectStateContext* /*ctx*/,
                          bool /*isUndo*/,
                          struct project_config_extension_t* /*reg*/)
{
    if (!line || !*line) return false;
    const char* p = line;
    while (*p == ' ' || *p == '\t') ++p;
    if (std::strncmp(p, "PG_ACTIVE", 9) == 0) {
        p += 9;
        while (*p == ' ' || *p == '\t') ++p;
        uf8::param_groups::applyActiveFlags(p);
        return true;
    }
    if (std::strncmp(p, "PG_NAME", 7) == 0) {
        p += 7;
        while (*p == ' ' || *p == '\t') ++p;
        int slot = 0;
        while (*p >= '0' && *p <= '9') { slot = slot * 10 + (*p - '0'); ++p; }
        while (*p == ' ' || *p == '\t') ++p;
        if (*p == '"') ++p;
        std::string name;
        while (*p && *p != '"') name += *p++;
        uf8::param_groups::applyGroupName(slot, name.c_str());
        return true;
    }
    return false;
}

void pgActiveBeginLoad_(bool /*isUndo*/,
                        struct project_config_extension_t* /*reg*/)
{
    // New / loading project: all groups off + unnamed until the project's
    // PG_ACTIVE / PG_NAME lines restore them.
    uf8::param_groups::resetActiveFlags();
    uf8::param_groups::resetGroupNames();
}

project_config_extension_t g_pgActiveProjConfig{
    pgActiveProcessLine_,
    pgActiveSaveExt_,
    pgActiveBeginLoad_,
    nullptr
};

// Temporary-selection-set persistence: TAB-joined GUIDs in ProjExtState
// key "temp_selset", recall flag in "temp_selset_active" ("1" / ""). Per-
// project (so a working set saved in Project A doesn't leak into Project
// B). Called by tempSelsetWriteToProject_ on every mutation, and by
// loadSelsetsFromProject_ on project switch.
constexpr char kTempSelsetDelim = '\t';
// Persistence runs through the projectconfig hooks below, NOT through
// SetProjExtState. The session of 2026-05-27 proved that SetProjExtState
// writes were accepted in-memory (readback worked) but REAPER never
// serialised them to the saved .rpp — even with MarkProjectDirty +
// explicit project pointer. The official `project_config_extension_t`
// pattern (SaveExtensionConfig / ProcessExtensionLine) puts our lines
// directly into the .rpp chunk REAPER writes, bypassing whatever
// ExtState quirk lost the data.
//
// tempSelsetWriteToProject_ is therefore now just a "mark project as
// needing save" trigger so the user gets the standard Save prompt /
// star indicator after touching the temp set. Actual disk write is
// driven by REAPER calling tempSelsetSaveExt_ from the projectconfig
// hook on Cmd+S.
void tempSelsetWriteToProject_() {
    if (ReaProject* p = EnumProjects(-1, nullptr, 0)) {
        MarkProjectDirty(p);
    }
}

// projectconfig SaveExtensionConfig — REAPER calls this during a
// project save. We write two RPP chunk lines that REAPER stores
// verbatim and feeds back via ProcessExtensionLine on the next load.
// Format uses quoted strings so the LineParser keeps tabs / spaces
// intact inside the GUID list.
void tempSelsetSaveExt_(ProjectStateContext* ctx, bool /*isUndo*/,
                        struct project_config_extension_t* /*reg*/)
{
    std::string joined;
    bool first = true;
    for (const auto& g : g_tempSelsetGuids) {
        if (!first) joined += '\t';
        joined += g;
        first = false;
    }
    if (!joined.empty()) {
        ctx->AddLine("TEMPSELSET_DATA \"%s\"", joined.c_str());
    }
    if (g_tempSelsetActive.load()) {
        ctx->AddLine("TEMPSELSET_ACTIVE 1");
    }
}

bool tempSelsetProcessLine_(const char* line, ProjectStateContext* /*ctx*/,
                            bool /*isUndo*/,
                            struct project_config_extension_t* /*reg*/)
{
    if (!line || !*line) return false;
    const char* p = line;
    while (*p == ' ' || *p == '\t') ++p;
    if (std::strncmp(p, "TEMPSELSET_DATA", 15) == 0) {
        p += 15;
        while (*p == ' ' || *p == '\t') ++p;
        if (*p == '"') ++p;
        std::string field;
        while (*p && *p != '"') field += *p++;
        size_t pos = 0;
        while (pos <= field.size()) {
            size_t next = field.find('\t', pos);
            std::string g = (next == std::string::npos)
                            ? field.substr(pos) : field.substr(pos, next - pos);
            if (!g.empty()) g_tempSelsetGuids.insert(std::move(g));
            if (next == std::string::npos) break;
            pos = next + 1;
        }
        return true;
    }
    if (std::strncmp(p, "TEMPSELSET_ACTIVE", 17) == 0) {
        p += 17;
        while (*p == ' ' || *p == '\t') ++p;
        g_tempSelsetActive.store(*p == '1');
        return true;
    }
    return false;
}

void tempSelsetBeginLoad_(bool /*isUndo*/,
                          struct project_config_extension_t* /*reg*/)
{
    g_tempSelsetGuids.clear();
    g_tempSelsetActive.store(false);
}

project_config_extension_t g_tempSelsetProjConfig{
    tempSelsetProcessLine_,
    tempSelsetSaveExt_,
    tempSelsetBeginLoad_,
    nullptr
};

// Load now flows through the projectconfig BeginLoadProjectState +
// ProcessExtensionLine callbacks driven by REAPER. Stub kept so the
// existing call from loadSelsetsFromProject_ compiles and so that
// dylib reloads in the middle of an already-open project still pick
// up state — but the moment a real save / load round trip happens,
// REAPER's projectconfig path wins.
void tempSelsetLoadFromProject_(ReaProject* /*proj*/) {
    // No-op — projectconfig hook owns load.
}

void loadSelsetsFromProject_() {
    ReaProject* proj = EnumProjects(-1, nullptr, 0);
    // Per-slot scope flag lives in global ExtState (reliable). For
    // global-scoped slots the data also lives there; for project-scoped
    // slots the data is fed in by the projectconfig hook
    // (slotsProcessLine_) before this drain runs, so we don't read the
    // .rpp directly here. SetProjExtState was unreliable on Frank's
    // build — see setprojextstate-not-reliable.md.
    for (int i = 1; i <= 8; ++i) {
        char flagKey[32], globalKey[32];
        selsetKeyFlag_(i,        flagKey,   sizeof(flagKey));
        selsetKeyDataGlobal_(i,  globalKey, sizeof(globalKey));
        const char* flagStr = GetExtState("rea_sixty", flagKey);
        const bool isGlobal = flagStr && *flagStr
                            && std::strcmp(flagStr, "global") == 0;
        if (isGlobal) {
            char val[8192] = {0};
            const char* d = GetExtState("rea_sixty", globalKey);
            if (d && *d) std::strncpy(val, d, sizeof(val) - 1);
            if (val[0]) selsetDeserialize_(val, g_selsets[i - 1]);
            else        g_selsets[i - 1] = SelSet{};
            g_selsets[i - 1].global = true;
        } else {
            // Project-scoped — the projectconfig hook already populated
            // g_selsets[i-1] for this project (or left it default-empty
            // if no SELSET_<N>_DATA line was present). Just refresh the
            // global flag so the in-memory state agrees with ExtState.
            g_selsets[i - 1].global = false;
        }
    }
    // Temp selset rides the same project-load tick — same dirty flag,
    // same source-of-truth project pointer. Kept simple (single set, no
    // global-vs-project switch); pure ProjExtState persistence.
    tempSelsetLoadFromProject_(proj);
    g_selsetsLoadedFor = proj;
    g_selsetsDirty.store(false);
}

// Walk a slot's resolved tracks (Snapshot: stored guids; Group: live
// group membership) and force REAPER auto-mode on each. Main-thread
// only — SetTrackAutomationMode is not thread-safe. `mode` = REAPER
// mode 0..5; out-of-range silently skips. No-op for an empty slot
// or slot index out of [1..8]. Powers the Settings → Modes → Auto
// "Selection-Set Auto-Mode" feature: caller picks the slot (the
// active one on recall / the outgoing one on deactivate) and the
// target mode (g_selsetAutoMode on apply / 0 on revert).
void selsetApplyAutoModeToSlot_(int slot1to8, int mode)
{
    if (slot1to8 < 1 || slot1to8 > 8) return;
    if (mode < 0 || mode > 5) return;
    const SelSet& s = g_selsets[slot1to8 - 1];
    auto applyOne = [&](MediaTrack* tr) {
        if (!tr || !ValidatePtr2(nullptr, tr, "MediaTrack*")) return;
        if (GetTrackAutomationMode(tr) == mode) return;   // idempotent
        SetTrackAutomationMode(tr, mode);
    };
    if (s.type == SelSetType::Snapshot) {
        // Resolve each stored GUID against the current project's tracks.
        const int n = CountTracks(nullptr);
        std::unordered_set<std::string> wanted(s.guids.begin(), s.guids.end());
        for (int i = 0; i < n; ++i) {
            MediaTrack* tr = GetTrack(nullptr, i);
            if (!tr) continue;
            char gb[64] = {0};
            GetSetMediaTrackInfo_String(tr, "GUID", gb, false);
            if (wanted.count(gb)) applyOne(tr);
        }
    } else {
        // Group: live membership lookup, same as refreshActiveSelsetGuids_.
        const int n = CountTracks(nullptr);
        for (int i = 0; i < n; ++i) {
            MediaTrack* tr = GetTrack(nullptr, i);
            if (!tr) continue;
            if (trackInGroup_(tr, s.groupIdx)) applyOne(tr);
        }
    }
}

// Twin of selsetApplyAutoModeToSlot_ for the Temporary Selection Set.
// Walks g_tempSelsetGuids against the current project's tracks and
// forces each to `mode`. Same idempotency guard.
void tempSelsetApplyAutoMode_(int mode)
{
    if (mode < 0 || mode > 5) return;
    if (g_tempSelsetGuids.empty()) return;
    const int n = CountTracks(nullptr);
    for (int i = 0; i < n; ++i) {
        MediaTrack* tr = GetTrack(nullptr, i);
        if (!tr) continue;
        char gb[64] = {0};
        GetSetMediaTrackInfo_String(tr, "GUID", gb, false);
        if (!g_tempSelsetGuids.count(gb)) continue;
        if (GetTrackAutomationMode(tr) == mode) continue;
        SetTrackAutomationMode(tr, mode);
    }
}

void refreshActiveSelsetGuids_() {
    g_selsetActiveGuids.clear();
    const int slot = g_selsetActive.load();
    if (slot < 1 || slot > 8) return;
    const SelSet& s = g_selsets[slot - 1];
    if (s.type == SelSetType::Snapshot) {
        for (const auto& g : s.guids) g_selsetActiveGuids.insert(g);
    } else {
        const int n = CountTracks(nullptr);
        for (int i = 0; i < n; ++i) {
            MediaTrack* tr = GetTrack(nullptr, i);
            if (!tr) continue;
            if (trackInGroup_(tr, s.groupIdx)) {
                g_selsetActiveGuids.insert(trackGuidStr_(tr));
            }
        }
    }
}

void saveCurrentSelectionToSlot_(int slot1to8) {
    if (slot1to8 < 1 || slot1to8 > 8) return;
    SelSet& s = g_selsets[slot1to8 - 1];
    // Save always produces a Snapshot slot. If the slot was previously
    // bound to a Group, this overwrites the binding — user choice.
    s.type = SelSetType::Snapshot;
    s.guids.clear();
    const int n = CountTracks(nullptr);
    for (int i = 0; i < n; ++i) {
        MediaTrack* tr = GetTrack(nullptr, i);
        if (!tr) continue;
        if (GetMediaTrackInfo_Value(tr, "I_SELECTED") > 0.5) {
            s.guids.push_back(trackGuidStr_(tr));
        }
    }
    selsetWriteToProject_(slot1to8);
    if (g_selsetActive.load() == slot1to8) refreshActiveSelsetGuids_();
    g_bankDirty.store(true);
}

// Temp-selset handler forward decls — bodies live further down in the
// same anonymous namespace (~line 13569). Declared at namespace scope
// rather than block-scope so MSVC links them to the internal-linkage
// definitions; block-scope decls inside drainSelsets_ would imply
// external linkage and produce LNK2019 on Win.
void tempSelsetAddSelected_();
void tempSelsetRemoveSelected_();
void tempSelsetToggleRecall_();
void tempSelsetClear_();
void tempSelsetToggleSelected_();
void tempSelsetSetFromSelection_();
void tempSelsetPinFocused_();

// onTimer drain. Detect project switch, then process queued recall /
// save requests, then refresh the active GUID set for Group slots so
// the next rebuildVisibleTrackList tick sees up-to-date membership.
void drainSelsets_() {
    ReaProject* curProj = EnumProjects(-1, nullptr, 0);
    if (curProj != g_selsetsLoadedFor) g_selsetsDirty.store(true);
    if (g_selsetsDirty.load()) {
        loadSelsetsFromProject_();
        if (g_selsetActive.load() > 0) refreshActiveSelsetGuids_();
        g_bankDirty.store(true);
    }
    const int saveReq = g_selsetSaveRequest.exchange(0);
    if (saveReq >= 1 && saveReq <= 8) saveCurrentSelectionToSlot_(saveReq);
    // CS-Switch: run the posted swap on the main thread (TrackFX_AddByName
    // floats a window → must not run on the input thread).
    // Plain Switch / Cycle follow the GLOBAL copy-mode toggle; the explicit
    // *_own requests always force own settings regardless.
    const bool csFavOwn = g_csFavOwnSettings.load();
    const bool bcFavOwn = g_bcFavOwnSettings.load();
    if (const int csSlot = g_csSwitchReq.exchange(-1); csSlot >= 0)
        applyCsSwitch_(csSlot, csFavOwn);
    if (const int csCopySlot = g_csCopyReq.exchange(-1); csCopySlot >= 0)
        applyCsCopy_(csCopySlot);
    if (const int csSteps = g_csCycleReq.exchange(0); csSteps != 0)
        applyCsCycle_(csSteps, csFavOwn);
    if (const int bcSlot = g_bcSwitchReq.exchange(-1); bcSlot >= 0)
        applyBcSwitch_(bcSlot, bcFavOwn);
    if (const int bcCopySlot = g_bcCopyReq.exchange(-1); bcCopySlot >= 0)
        applyBcCopy_(bcCopySlot);
    if (const int bcSteps = g_bcCycleReq.exchange(0); bcSteps != 0)
        applyBcCycle_(bcSteps, bcFavOwn);
    // Dynamic soft-key bank press (sends/FX/groups/colours) — executed on the
    // main thread; the input thread only posts the encoded request.
    if (const uint32_t dyn = g_dynBankReq.exchange(0); dyn != 0)
        applyDynBankReq_(dyn);
    // Reset bankable-bank pages on track change + drain posted page deltas
    // (defined after favContextTrack_ / the page state).
    tickDynBankPaging_();
    // FX move-in-chain posted by the REAPER action route (no on-screen carousel
    // there — the surface builtins drive that themselves).
    if (const int mvSteps = g_fxMoveReq.exchange(0); mvSteps != 0)
        applyFxMoveSlotAware_(mvSteps, /*carousel*/ false);
    const int actReq = g_selsetActivateRequest.exchange(0);
    // Capture the previously-active slot BEFORE mutating g_selsetActive
    // so the auto-mode revert can walk its tracks (Frank 2026-05-17:
    // deactivating a selset returns its tracks to Trim/Read = REAPER
    // mode 0). Same global g_selsetAutoMode drives every slot —
    // there's only one "what mode do recalled tracks land in?" knob
    // (Settings → Modes → Auto), not one per slot. selsetClear handles
    // its own inline revert because the membership data is gone by
    // the time the next drain runs.
    const int prevActive   = g_selsetActive.load();
    const int autoModeWant = g_selsetAutoMode.load();
    // Auto-mode apply/revert is gated on SelectionMode::Auto (Frank
    // 2026-05-19): outside Sel Mode Auto, selset recall is a pure
    // selection swap and must not touch REAPER automation modes.
    const bool autoModeGate =
        (g_selectionMode.load() == SelectionMode::Auto)
        && (autoModeWant >= 0);
    if (actReq == -1) {
        if (prevActive >= 1 && prevActive <= 8 && autoModeGate) {
            selsetApplyAutoModeToSlot_(prevActive, 0);
        }
        g_selsetActive.store(0);
        g_selsetActiveGuids.clear();
        g_bankDirty.store(true);
        g_pageDirty.store(true);   // re-paint global LEDs (selset_recall stateOf flipped)
        // Deactivating a selset typically widens the visible-tracks list
        // (the filter is gone), so the previously-selected track may sit
        // off-bank. Defer the follow via g_pendingFollowSelectedAfterRebuild
        // — onTimer consumes it after the next rebuildVisibleTrackList so
        // followSelectedInMixer sees the post-deactivate list. Frank 2026-05-21.
        if (prevActive >= 1 && prevActive <= 8) {
            g_pendingFollowSelectedAfterRebuild.store(true);
        }
    } else if (actReq >= 1 && actReq <= 8) {
        // Switching slots: revert the outgoing slot's auto-mode first
        // (only if a different slot was active and the global binding
        // is enabled, AND we're in Sel Mode Auto).
        if (prevActive >= 1 && prevActive <= 8 && prevActive != actReq
            && autoModeGate)
        {
            selsetApplyAutoModeToSlot_(prevActive, 0);
        }
        // Slot ↔ Temp are mutually exclusive — activating a slot
        // deactivates the temp set (and tempSelsetToggleRecall_ does
        // the reverse). Frank 2026-05-27.
        if (g_tempSelsetActive.load()) {
            // Revert temp's auto-mode before clearing the flag, same
            // gating as the slot-side. Mirrors the slot's outgoing
            // revert above so the user doesn't end up with temp's
            // members still armed after switching to a slot.
            if (autoModeGate) tempSelsetApplyAutoMode_(0);
            g_tempSelsetActive.store(false);
            tempSelsetWriteToProject_();
        }
        g_selsetActive.store(actReq);
        refreshActiveSelsetGuids_();
        // Snap the bank to the first channel of the selset so the surface
        // starts at strip 0 of the filtered list. Only on a real activation
        // (prevActive != actReq) — re-pressing the same selset key keeps
        // the user's banked position. Frank 2026-05-21.
        if (prevActive != actReq) {
            g_bankOffset.store(0);
        }
        // Apply the global auto-mode to the incoming slot's tracks.
        if (autoModeGate) {
            selsetApplyAutoModeToSlot_(actReq, autoModeWant);
        }
        g_bankDirty.store(true);
        g_pageDirty.store(true);
    }
    // Group slots: re-resolve every tick so adding/removing tracks
    // from the group in REAPER shows on the surface without a recall.
    const int slot = g_selsetActive.load();
    if (slot >= 1 && slot <= 8
        && g_selsets[slot - 1].type == SelSetType::Group)
    {
        refreshActiveSelsetGuids_();
    }

    // Temp-selset main-thread work. Drained AFTER the slot drain so a
    // recall toggle here sees the up-to-date g_selsetActive (the slot
    // path may have just deactivated a slot to honour mutual exclusion).
    // Handler bodies are defined later in this same anonymous namespace
    // (~line 13569); forward decls live at namespace scope above this
    // function so MSVC's linker doesn't treat block-scope `extern` decls
    // as a separate external symbol (Clang accepted both forms; MSVC
    // unresolved-externals'd on the Win build of v0.1.10).
    if (g_tempSelsetAddRequest.exchange(false)) {
        tempSelsetAddSelected_();
    }
    if (g_tempSelsetRemoveRequest.exchange(false)) {
        tempSelsetRemoveSelected_();
    }
    if (g_tempSelsetRecallRequest.exchange(false)) {
        tempSelsetToggleRecall_();
    }
    if (g_tempSelsetClearRequest.exchange(false)) {
        tempSelsetClear_();
    }
    if (g_tempSelsetSetFromSelRequest.exchange(false)) {
        tempSelsetSetFromSelection_();
    }
    if (g_tempSelsetToggleSelRequest.exchange(false)) {
        tempSelsetToggleSelected_();
    }
    if (g_tempSelsetPinFocusedRequest.exchange(false)) {
        tempSelsetPinFocused_();
    }
}

// Long-press SEL → folder spill toggle. Polled at the start of onTimer
// (before rebuildVisibleTrackList) so the rebuilt list immediately
// reflects spill changes. Skips silently when folder_mode is off — no
// visible effect even if user happens to long-press SEL.
//
// Toggle is per-folder only: collapsing removes just this entry,
// leaving any previously-spilled descendants in the set as dormant
// state. The strict-ancestor filter in rebuildVisibleTrackList hides
// them while this folder is collapsed, and a future re-spill restores
// the drill-down without any explicit snapshot.
void checkSelLongPressSpill() {
    if (!g_folderMode.load()) return;
    const int64_t now = nowMs_();
    for (int s = 0; s < 8; ++s) {
        const int64_t pressMs = g_selPressMs[s].load();
        if (pressMs == 0) continue;
        if (g_selSpillFired[s].load()) continue;
        if (now - pressMs < kSelLongPressMs) continue;
        g_selSpillFired[s].store(true);
        MediaTrack* tr = g_slotTrack[s];
        if (!tr || !ValidatePtr2(nullptr, tr, "MediaTrack*")) continue;
        // Only folder-start tracks (I_FOLDERDEPTH == 1) carry children
        // worth spilling. Non-folder top-level tracks fail this gate
        // and the long-press is a no-op for them.
        if (GetMediaTrackInfo_Value(tr, "I_FOLDERDEPTH") < 0.5) continue;
        if (g_spilledParents.count(tr)) g_spilledParents.erase(tr);
        else                            g_spilledParents.insert(tr);
        g_bankDirty.store(true);
    }
}

// (Selection-Set state moved up to be visible to rebuildVisibleTrackList —
//  declared near line 490 area.)

// V-Pot has dedicated Pan UX (Plugin button → plug-in Pan; PAN button →
// REAPER track pan; default → REAPER track pan). Clicking the Pan knob
// in the SSL plug-in GUI fires GetLastTouchedFX, which chaseLastTouchedFx
// turns into setFocus({ChannelStrip, 3}) — and that focus persists across
// Plugin/PAN button toggles, hijacking the V-Pot's Pan-mode tree. Fader
// + V-Pot drive/display sites treat Pan-focus as "no focus" so the
// Plugin/forcePan/REAPER tree retains authority over Pan.
inline bool isVPotPanFocus(const uf8::FocusedParam& f) {
    return f.domain == uf8::Domain::ChannelStrip && f.slotIdx == 3;
}

// Soft-Key Bank — which page of params is currently shown across the 8
// top-soft-key labels (and selectable via the per-strip 0x18..0x1F
// keys). Range is 0..5 (V-POT + Bank 1..5) for both domains; in BC
// mode banks 2..5 are present-but-empty per SSL UF8 User Guide.
// Layout from SSL UF8 User Guide p.180-181. Persisted across sessions.
std::atomic<int>  g_softKeyBank{0};
std::atomic<bool> g_softKeyDirty{false};
// When on (default), a focused-parameter change switches the SSL soft-key bank
// to whichever bank holds that param ("bank-follow-focus"). Off = the soft-key
// bank stays put when you touch a param. NEVER affects the UF8 parameter display
// (label/value re-push runs regardless). ExtState param_switches_softkey.
// Frank 2026-06-26.
std::atomic<bool> g_paramSwitchesSoftKeyBank{true};
// Latched soft-key DOMAIN (0 = Channel Strip, 1 = Bus Comp). The soft-key SSL view
// normally follows the focused param's domain; with bank-follow OFF it must stay put
// too (else touching a CS EQ while on a BC Quick flips the row to CS — Frank
// 2026-06-26). Updated from focused.domain while bank-follow is on, and on explicit
// domain selects; read by the soft-key push when bank-follow is off.
std::atomic<int> g_softKeyDomain{0};

// Unified favourite actions resolve their domain from the focused param; if the
// focus is neither CS nor BC (e.g. some other FX), fall back to the last latched
// CS/BC soft-key domain, else Channel Strip. Reads atomics only → input-thread-safe.
static bool favDomainIsBc_()
{
    const auto d = uf8::getFocusedParam().domain;
    if (d == uf8::Domain::BusComp)      return true;
    if (d == uf8::Domain::ChannelStrip) return false;
    return g_softKeyDomain.load() == 1;
}

// The domain the SSL soft-key row currently represents. With "Parameter change
// switches soft-key bank" ON it tracks the focused param's domain; with it OFF
// it stays on the latched g_softKeyDomain so a param touch in the other domain
// doesn't silently repoint soft-key DISPATCH while the row label stays put.
// Single source of truth for the label render AND every press-dispatch path so
// they never disagree (Frank Quick-2/BC desync: "label bleibt, aber Key-bank
// wechselt" 2026-06-26). Reads atomics only → input-thread-safe.
static uf8::Domain softKeyDomainNow_()
{
    if (g_paramSwitchesSoftKeyBank.load())
        return (uf8::getFocusedParam().domain == uf8::Domain::BusComp)
            ? uf8::Domain::BusComp : uf8::Domain::ChannelStrip;
    return (g_softKeyDomain.load() == 1)
        ? uf8::Domain::BusComp : uf8::Domain::ChannelStrip;
}

// UF8 Plugin Mode fader-bank (Frank 2026-05-17). Toggles between 0
// (strips 1-8 of a logical 16-strip plug-in like SSL Sigma) and 1
// (strips 9-16). Bank ←/→ buttons drive this while UF8 Plugin Mode is
// engaged; outside Plugin Mode the buttons fall back to their bindable
// builtin (±8-strip scroll by default). Persisted in ExtState so it
// survives reload, defaults to 0 on fresh boot.
std::atomic<int>  g_uf8FaderBank{0};

namespace softkey {
    constexpr int kNoSlot = -1;
    constexpr size_t kStrips = 8;

    // CS-mode banks (6 × 8). Values are SSL 360 Link slot indices
    // (linkIdx); uf8::ext::* refers to extension-defined synthetic IDs in
    // PluginMap.h for params not in the SSL 360 Link table.
    //   - Phase / A/B / HQ Mode: synthetic linkIdx — soft-key press sets
    //     focus to the synthetic, render path reads state per-strip
    //     (REAPER B_PHASE for Phase; SSL plug-in chunk for A/B + HQ),
    //     V-Pot push triggers the per-strip toggle. Same UX as any
    //     other CS param.
    //   - Pre / Mic-Drive / Imp In / Imp: only on 4K-series; CS2 strips
    //     render blank when soft-key pressed (graceful no-op).
    constexpr int kCsBanks[6][kStrips] = {
        // V-POT: BYPASS, IN TRIM, Ø, PRE, MIC/DRIVE, _, IMPEDANCE IN, IMPEDANCE
        // BYPASS uses linkIdx 0 — the plug-in's own Bypass param (NOT
        // REAPER's TrackFX_Enabled).
        { 0,  4, uf8::ext::TrackPhase, uf8::ext::Pre, uf8::ext::MicDrive, kNoSlot, uf8::ext::ImpedanceIn, uf8::ext::Impedance },
        // Bank 1: WIDTH, _, _, A/B, HIGH PASS, LOW PASS, EQ, EQ TYPE
        { 2, kNoSlot, kNoSlot, uf8::ext::PluginAB,  7,  6, 15, 14 },
        // Bank 2: LF FREQ, LF GAIN, LF TYPE, _, LMF FREQ, LMF GAIN, LMF Q, _
        { 19, 20, 21, kNoSlot, 17, 16, 18, kNoSlot },
        // Bank 3: HMF FREQ, HMF GAIN, HMF Q, _, _, HF FREQ, HF GAIN, HF TYPE
        { 12, 11, 13, kNoSlot, kNoSlot, 10,  9,  8 },
        // Bank 4: DYNAMICS, COMP MIX, COMP RATIO, COMP THR, COMP REL, COMP ATK, PEAK/RMS, _
        { 22, 23, 26, 27, 28, 24, 25, kNoSlot },
        // Bank 5: GATE REL, GATE THR, GATE RNG, GATE HLD, GATE ATK, GATE/EXP, HQ MODE, OUT TRIM
        { 31, 30, 29, 32, 34, 33, uf8::ext::PluginHQ, 37 },
    };
    constexpr const char* kCsLabels[6][kStrips] = {
        { "BYPASS",  "IN TRIM",   "PHASE",      "PRE",      "MIC/DRV",   "",          "IMP IN",  "IMP" },
        { "WIDTH",   "",          "",           "A/B",      "HPF",       "LPF",       "EQ",      "EQ TYPE" },
        { "LF FREQ", "LF GAIN",   "LF TYPE",    "",         "LMF FREQ",  "LMF GAIN",  "LMF Q",   "" },
        { "HMF FREQ","HMF GAIN",  "HMF Q",      "",         "",          "HF FREQ",   "HF GAIN", "HF TYPE" },
        { "DYNAMICS","COMP MIX",  "COMP RATIO", "COMP THR", "COMP REL",  "COMP F.ATK","PEAK/RMS","" },
        { "GATE REL","GATE THR",  "GATE RANGE", "GATE HOLD","GATE F.ATK","GATE/EXP",  "HQ MODE", "OUT TRIM" },
    };

    // BC-mode banks (6 × 8). Banks 2..5 are intentionally empty per SSL
    // UF8 User Guide — bank navigation cycles through them symmetrically
    // with CS mode even though BC has only two pages of params.
    constexpr int kBcBanks[6][kStrips] = {
        // V-POT: THRESHOLD, ATTACK, RELEASE, RATIO, S/C HPF, MIX, EXTERNAL S/C, BUS COMP
        // BUS COMP at pos 7 = the BC plug-in's own CompBypass param
        // (linkIdx 0 in the BC 360 Link layout). External S/C uses
        // uf8::ext::ExternalSC — only the Native BC2 plug-in exposes it (the
        // 360 Link wrapper does not), so other BC variants will no-op.
        { 1, 3, 4, 5, 6, 7, uf8::ext::ExternalSC, 0 },
        // Bank 1: OUTPUT GAIN (= MakeupGain in BC2 map), rest empty
        { 2, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot },
        // Banks 2..5: empty per SSL spec
        { kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot },
        { kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot },
        { kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot },
        { kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot, kNoSlot },
    };
    constexpr const char* kBcLabels[6][kStrips] = {
        { "THR",    "ATTACK", "RELEASE","RATIO", "S/C HPF","MIX",  "EXT S/C","BUS COMP" },
        { "OUTGAIN","",       "",       "",      "",       "",     "",       "" },
        { "",       "",       "",       "",      "",       "",     "",       "" },
        { "",       "",       "",       "",      "",       "",     "",       "" },
        { "",       "",       "",       "",      "",       "",     "",       "" },
        { "",       "",       "",       "",      "",       "",     "",       "" },
    };

    constexpr int kCsMaxBank = 5;
    constexpr int kBcMaxBank = 5;

    // Domain-aware bank max so the bank index can be clamped after a
    // domain switch (BC has fewer banks than CS).
    inline int maxBankFor(uf8::Domain d) {
        return d == uf8::Domain::BusComp ? kBcMaxBank : kCsMaxBank;
    }

    // Resolve the current 8-slot view (linkIdx + label arrays) for a
    // given domain + bank. Caller clamps bank to maxBankFor(domain).
    struct View {
        const int*        linkIdx;
        const char* const* labels;
    };
    inline View viewFor(uf8::Domain d, int bank) {
        if (d == uf8::Domain::BusComp) {
            return { kBcBanks[bank], kBcLabels[bank] };
        }
        return { kCsBanks[bank], kCsLabels[bank] };
    }

    // Find which bank in `domain` contains a given linkIdx. -1 if not
    // found. Used to auto-follow the bank to externally-set focus
    // (UC1 knob, plugin GUI mouse, FocusedFX chase).
    inline int bankContaining(uf8::Domain d, int linkIdx) {
        const int max = maxBankFor(d);
        for (int b = 0; b <= max; ++b) {
            const View v = viewFor(d, b);
            for (size_t s = 0; s < kStrips; ++s) {
                if (v.linkIdx[s] == linkIdx) return b;
            }
        }
        return -1;
    }
}

// Per-strip cache for the SEL-follows-DAW-Colour LED state. Avoids
