// CS-Switch favourites (2026-06-20): up to 8 Channel-Strip plug-in identities
// the user can jump to ("Switch to CS N") or cycle through ("CS Cycle"). Each
// switch REPLACES the track's active CS instance with the favourite, carrying
// over the values of params that share a surface control (matched by linkIdx).
//   addName = TrackFX_AddByName string — the fxIdentityName / user-map match,
//             the same string the FX-Learn editor feeds to TrackFX_AddByName.
//   label   = display name for the Settings + Learn-HUD dropdowns.
// One plug-in occupies at most one slot (assigning steals it from any other).
// Persisted globally (survives restart, all projects) as "cs_favourites2" — ONE
// line, tab-separated add<TAB>label pairs by slot position. NO newline: the
// reaper-extstate.ini is line-based, so an embedded '\n' only round-trips the
// first slot (the "forgets favourites" bug). Old "cs_favourites" key abandoned.
// Touched only on the main thread (Settings UI + the onTimer-drained switch);
// the mutex guards against a stray Learn-HUD read while the UI rewrites a slot.
struct CsFav { std::string addName; std::string label; };
std::array<CsFav, 8> g_csFav;
std::mutex           g_csFavMutex;

static void saveCsFavourites_locked_()
{
    // SINGLE LINE — persistent ExtState lands in the line-based
    // reaper-extstate.ini, so an embedded '\n' breaks the round-trip and only
    // the first slot survives a restart (was the "forgets favourites" bug). All
    // 8 slots are written by position as tab-separated add\tlabel pairs (16
    // fields + trailing tab); plug-in names never contain a tab or newline.
    std::string out;
    for (int i = 0; i < 8; ++i) {
        out += g_csFav[i].addName;   // empty for unset slots
        out += '\t';
        out += g_csFav[i].label;
        out += '\t';
    }
    SetExtState("rea_sixty", "cs_favourites2", out.c_str(), true);
}

// Bus-Compressor favourites — exact analog of the CS favourites above (8 slots,
// global, single-line ExtState "bc_favourites"). Reuses the CsFav struct (it's
// just add-name + label). "Switch to BC N" / "Copy to BC N" / "BC Cycle" replace
// the track's active Bus Compressor with the favourite, carrying the 8 shared
// BC params across (or restoring per-favourite memory in "own settings" mode).
// Frank 2026-06-26.
std::array<CsFav, 8> g_bcFav;
std::mutex           g_bcFavMutex;

static void saveBcFavourites_locked_()
{
    std::string out;
    for (int i = 0; i < 8; ++i) {
        out += g_bcFav[i].addName;
        out += '\t';
        out += g_bcFav[i].label;
        out += '\t';
    }
    SetExtState("rea_sixty", "bc_favourites", out.c_str(), true);
}

// Per-project favourite bank override (Phase 2). When `active`, the PROJECT's own
// 8 CS + 8 BC favourites override the global ExtState set; otherwise the global
// set is used — so a fresh project inherits the last-used (global) favourites.
// Persisted per project via g_favBankProjConfig (CSFAVBANK / BCFAVBANK lines).
// Seeded from the global set the first time it's enabled. Main-thread only.
struct ProjFavBank {
    bool                 active = false;
    std::array<CsFav, 8> cs;
    std::array<CsFav, 8> bc;
};
ProjFavBank g_projFavBank;

// Assign `name` to slot in an 8-slot favourite array, stealing it from any other
// slot it occupied (mirrors reasixty_setCsFav's one-plug-in-one-slot rule). Empty
// name clears the slot.
static void setFavInArray_(std::array<CsFav, 8>& arr, int slot,
                           const char* addName, const char* label)
{
    if (slot < 0 || slot >= 8) return;
    const std::string name = addName ? addName : "";
    if (name.empty()) { arr[slot].addName.clear(); arr[slot].label.clear(); return; }
    for (int i = 0; i < 8; ++i)
        if (i != slot && arr[i].addName == name) { arr[i].addName.clear(); arr[i].label.clear(); }
    arr[slot].addName = name;
    arr[slot].label   = (label && *label) ? label : name;
}

// ---- Named favourite Set libraries (Phase 3, CS/BC split 2026-06-26) --------
// CS and BC favourite sets are SEPARATE libraries: a CS set holds 8 Channel-Strip
// favourites, a BC set holds 8 Bus-Comp favourites. A track is assigned ONE CS set
// and ONE BC set, independently. Both libraries live GLOBAL in
// <RESOURCE>/rea_sixty/favourite_sets.txt (simple TAB line format, no JSON dep);
// the per-track assignments are PER PROJECT (.rpp, via the favBank projectconfig
// hook). Resolution at action time, against the focused/context track:
//   track's assigned CS/BC set → base bank (project override else global).
struct NamedFavSet {
    std::string          name;
    std::array<CsFav, 8> slots;
};
std::vector<NamedFavSet>           g_csSets;        // Channel-Strip set library
std::vector<NamedFavSet>           g_bcSets;        // Bus-Comp set library
std::map<std::string, std::string> g_trackCsSet;   // trackGUID → CS-set name
std::map<std::string, std::string> g_trackBcSet;   // trackGUID → BC-set name

static std::vector<NamedFavSet>&          favLib_(bool cs)       { return cs ? g_csSets : g_bcSets; }
static std::map<std::string, std::string>& favAssignMap_(bool cs) { return cs ? g_trackCsSet : g_trackBcSet; }

static std::string favSetsFilePath_()
{
    const char* base = GetResourcePath ? GetResourcePath() : nullptr;
    std::string d = (base && *base) ? base : ".";
    d += "/rea_sixty";
#ifdef _WIN32
    _mkdir(d.c_str());
#else
    mkdir(d.c_str(), 0755);
#endif
    return d + "/favourite_sets.txt";
}

// File format (current — one record per Set, CS and BC libraries in turn):
//   CSSET\t<name>   |   BCSET\t<name>
//   S\t<slot>\t<addName>\t<label>      (belongs to the most recent CSSET/BCSET)
// Legacy (combined Phase-3 sets) is still READ on load — SET/CS/BC — and migrated
// into a same-named CS set + BC set. The next save re-writes in the new format.
static void favSetsSave_()
{
    std::string out;
    auto writeLib = [&out](const char* tag, const std::vector<NamedFavSet>& lib) {
        for (const auto& s : lib) {
            out += tag; out += '\t'; out += s.name; out += '\n';
            for (int i = 0; i < 8; ++i)
                if (!s.slots[i].addName.empty())
                    out += "S\t" + std::to_string(i) + '\t' + s.slots[i].addName + '\t' + s.slots[i].label + '\n';
        }
    };
    writeLib("CSSET", g_csSets);
    writeLib("BCSET", g_bcSets);
    const std::string path = favSetsFilePath_();
    const std::string tmp = path + ".tmp";
    if (FILE* f = std::fopen(tmp.c_str(), "wb")) {
        if (!out.empty()) std::fwrite(out.data(), 1, out.size(), f);
        std::fclose(f);
        std::rename(tmp.c_str(), path.c_str());
    }
}

static void favSetsLoad_()
{
    g_csSets.clear(); g_bcSets.clear();
    FILE* f = std::fopen(favSetsFilePath_().c_str(), "rb");
    if (!f) return;
    std::fseek(f, 0, SEEK_END); long n = std::ftell(f); std::fseek(f, 0, SEEK_SET);
    std::string buf;
    if (n > 0) { buf.resize(static_cast<size_t>(n)); std::fread(buf.data(), 1, buf.size(), f); }
    std::fclose(f);

    size_t pos = 0;
    auto nextField = [](const std::string& line, size_t& p) -> std::string {
        const size_t t = line.find('\t', p);
        std::string out = (t == std::string::npos) ? line.substr(p) : line.substr(p, t - p);
        p = (t == std::string::npos) ? line.size() : t + 1;
        return out;
    };
    auto putSlot = [&](std::vector<NamedFavSet>& lib, int idx,
                       int slot, const std::string& add, const std::string& label) {
        if (idx < 0 || idx >= static_cast<int>(lib.size()) || slot < 0 || slot >= 8) return;
        lib[idx].slots[slot].addName = add;
        lib[idx].slots[slot].label   = label.empty() ? add : label;
    };
    bool curCs = true; int curIdx = -1;            // new-format "S" target
    int legacyCs = -1, legacyBc = -1;              // legacy "CS"/"BC" targets
    while (pos < buf.size()) {
        size_t nl = buf.find('\n', pos);
        std::string line = (nl == std::string::npos) ? buf.substr(pos) : buf.substr(pos, nl - pos);
        pos = (nl == std::string::npos) ? buf.size() : nl + 1;
        if (line.empty()) continue;
        size_t p = 0;
        const std::string tag = nextField(line, p);
        if (tag == "CSSET") {
            NamedFavSet s; s.name = line.substr(p);
            g_csSets.push_back(std::move(s));
            curCs = true; curIdx = static_cast<int>(g_csSets.size()) - 1;
        } else if (tag == "BCSET") {
            NamedFavSet s; s.name = line.substr(p);
            g_bcSets.push_back(std::move(s));
            curCs = false; curIdx = static_cast<int>(g_bcSets.size()) - 1;
        } else if (tag == "S") {
            const int slot = std::atoi(nextField(line, p).c_str());
            const std::string add = nextField(line, p);
            putSlot(favLib_(curCs), curIdx, slot, add, line.substr(p));
        } else if (tag == "SET") {                 // legacy combined set → split
            NamedFavSet cs; cs.name = line.substr(p);
            NamedFavSet bc; bc.name = cs.name;
            g_csSets.push_back(std::move(cs));     legacyCs = static_cast<int>(g_csSets.size()) - 1;
            g_bcSets.push_back(std::move(bc));     legacyBc = static_cast<int>(g_bcSets.size()) - 1;
        } else if (tag == "CS" || tag == "BC") {   // legacy slot line
            const int slot = std::atoi(nextField(line, p).c_str());
            const std::string add = nextField(line, p);
            if (tag == "CS") putSlot(g_csSets, legacyCs, slot, add, line.substr(p));
            else             putSlot(g_bcSets, legacyBc, slot, add, line.substr(p));
        }
    }
}

static int setIndexByName_(bool cs, const std::string& name)
{
    const auto& lib = favLib_(cs);
    for (size_t i = 0; i < lib.size(); ++i)
        if (lib[i].name == name) return static_cast<int>(i);
    return -1;
}

// The track a favourite gesture resolves against: focused track, else first
// selected. Main-thread only.
static MediaTrack* favContextTrack_()
{
    MediaTrack* tr = g_uc1_surface
        ? static_cast<MediaTrack*>(g_uc1_surface->focusedTrack()) : nullptr;
    if (!tr) tr = GetSelectedTrack(nullptr, 0);
    return tr;
}

// The CS (cs=true) or BC (cs=false) set a track resolves to via its per-project
// assignment, or nullptr (→ caller falls back to the base bank).
static const NamedFavSet* setForTrack_(bool cs, MediaTrack* tr)
{
    if (!tr) return nullptr;
    const auto& m = favAssignMap_(cs);
    const auto it = m.find(trackGuidStr_(tr));
    if (it == m.end()) return nullptr;
    const int si = setIndexByName_(cs, it->second);
    return (si >= 0) ? &favLib_(cs)[si] : nullptr;
}

