    if (std::sscanf(p, " %d %d %lf %lf %d %d %d %d",
                    &key, &num, &norm, &eng, &kind, &dim, &sIdx, &sCnt) != 8)
        return true;
    if (key < 0 || key >= 128) return true;
    CsVal v;
    v.valid = true;  v.numeric = (num != 0);  v.norm = norm;  v.eng = eng;
