    const std::string dir         = scriptsRoot + "/rea-sixty";
#ifdef _WIN32
    _mkdir(scriptsRoot.c_str());
    _mkdir(dir.c_str());
#else
    mkdir(scriptsRoot.c_str(), 0755);
    mkdir(dir.c_str(), 0755);
#endif
